'use strict';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const ICONS={home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',map:'m9 4-6 3v14l6-3 6 3 6-3V4l-6 3-6-3ZM9 4v14m6-11v14',stack:'m3 6 9-4 9 4-9 4-9-4Zm0 6 9 4 9-4M3 18l9 4 9-4',bookmark:'M6 3h12v19l-6-4-6 4V3Z',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v6l4 2',heart:'M12 20S2 14 2 8a5 5 0 0 1 10-1A5 5 0 0 1 22 8c0 6-10 12-10 12Z',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',globe:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Zm0 0c-6 6-6 14 0 20m0-20c6 6 6 14 0 20M2 12h20',play:'m8 4 12 8-12 8V4Z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z',grid:'M3 3h7v7H3V3Zm11 0h7v7h-7V3ZM3 14h7v7H3v-7Zm11 0h7v7h-7v-7Z',list:'M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1',close:'m6 6 12 12M6 18 18 6',menu:'M3 6h18M3 12h18M3 18h18'};
function icons(){document.querySelectorAll('i[data-icon]').forEach(e=>e.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[e.dataset.icon]||ICONS.play}"/></svg>`)}
function read(k,f){try{return JSON.parse(localStorage.getItem('pt-'+k))??f}catch{return f}}
function write(k,v){try{localStorage.setItem('pt-'+k,JSON.stringify(v))}catch{toast('This browser cannot save changes. You can still explore.')}}
let saved=read('saved',[]),history=read('history',[]),practiceOnly=read('practice',false);if(!Array.isArray(saved))saved=[];if(!Array.isArray(history))history=[];
let view='home',category='all',query='',layout='grid',selectedLesson=null,active=null,wordIndex=0,revealed=false,finished=false;
const ALL=[...VIDEOS,...PRACTICE],tones=['#dae4ff','#ffe7aa','#dce9ff','#eadff8','#ffd9cc','#f9dfbd'];
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function time(s){return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
function lessonLabel(v){if(v.lessons){return 'LESSON '+v.lesson+(v.lessons.length>1?' + '+(v.lessons.length-1)+' review'+(v.lessons.length>2?'s':''):'')}return 'LESSON '+v.lesson+(v.end!==v.lesson?'–'+v.end:'')}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function searchMatches(v){const q=query.trim().toLowerCase();if(!q)return true;const numeric=q.match(/^(?:lesson\s*)?(\d+)$/);if(numeric)return supportsLesson(v,+numeric[1]);return [v.title,v.creator,v.sound,v.subtitle,v.group,v.sourceTitle||''].join(' ').toLowerCase().includes(q)}
function matches(v){return(!practiceOnly||v.kind==='practice')&&(category==='all'||category===v.group||(v.groups||[]).includes(category))&&(!selectedLesson||supportsLesson(v,selectedLesson))&&searchMatches(v)}
function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];write('saved',saved);toast(saved.includes(id)?'Saved for a little later.':'Removed from watch later.');render()}
function card(v){const isSaved=saved.includes(v.id);return `<article class="card"><button class="thumbnail" data-open="${v.id}" style="--tone:${tones[v.tone]}" aria-label="${esc(v.kind==='practice'?'Practise: ':'Watch: ')}${esc(v.title)}"><div class="thumb-top">${v.kind==='practice'?'PHONICS TUBE · WORD PRACTICE':'A LITTLE PHONICS DISCOVERY'}</div><div class="thumb-word" style="${v.sound.length>10?'font-size:clamp(20px,2.5vw,37px)':''}">${esc(v.sound)}</div><div class="thumb-sub">${esc(v.subtitle)}</div><span class="thumb-shape"></span><span class="play-circle">${v.kind==='practice'?'✦':'▶'}</span><span class="thumb-time">${v.kind==='practice'?'SELF-PACED':time(v.seconds)}</span></button><div class="card-topline"><div><span class="lesson-tag">${lessonLabel(v)}</span><span class="card-category">${esc(GROUPS.find(g=>g[0]===v.group)[1])}</span></div><button class="save ${isSaved?'saved':''}" data-save="${v.id}" aria-label="${isSaved?'Remove from':'Save to'} watch later: ${esc(v.title)}" aria-pressed="${isSaved}"><i data-icon="bookmark"></i></button></div><h3><button data-open="${v.id}">${esc(v.title)}</button></h3><div class="creator">${esc(v.creator)}</div><div class="card-meta">${v.kind==='practice'?'<span class="practice-badge">Works without YouTube</span>':`<i data-icon="clock"></i> ${time(v.seconds)} <span>·</span> <span>YouTube</span> <span>·</span> <span>Preview together</span>`}</div></article>`}
function empty(title,text){return `<div class="empty"><span class="completion">✦</span><h3>${title}</h3><p>${text}</p><button class="primary" id="reset">Explore all discoveries</button></div>`}
function render(){const titles={home:['PICK A SOUND. PRESS PLAY.','Your next little discovery','Good things come in small lessons.'],saved:['SAVE A LITTLE FOR LATER.','Your saved discoveries','A pocketful of sounds, ready when you are.'],history:['LOOK HOW FAR YOU’VE EXPLORED.','Recently explored','Return to a favourite little discovery.'],lessons:['ONE SOUND AT A TIME.','Explore the lesson path','All 128 lessons, in the order of your classroom learning.'],playlists:['A LITTLE PATH TO FOLLOW.','Learning playlists','A few discoveries that belong together.']};const t=titles[view];$('#hero').hidden=view!=='home';$('#section-eyebrow').textContent=t[0];$('#section-title').textContent=selectedLesson?'Lesson '+selectedLesson+': '+LESSON_NAMES[selectedLesson-1]:t[1];$('#section-description').textContent=selectedLesson?'Resources supporting this lesson. Check the alignment note before watching.':t[2];$('#crumb').textContent={home:'Discover',saved:'Watch later',history:'Recently explored',lessons:'Lesson explorer',playlists:'Playlists'}[view];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#saved-count').textContent=saved.length||'';$('.nav-badge').textContent=ALL.length;$('#mode').setAttribute('aria-pressed',practiceOnly);$('#mode span').textContent=practiceOnly?'Practice only':'All resources';$('#filters').innerHTML=GROUPS.map(g=>`<button class="chip ${category===g[0]?'active':''}" data-category="${g[0]}" aria-pressed="${category===g[0]}">${g[1]}</button>`).join('');$('#filter-summary').textContent=practiceOnly?'Built-in word practice · no YouTube needed':selectedLesson?'Supporting this lesson':category==='all'?'A little of everything, just for you':GROUPS.find(g=>g[0]===category)[1];$('.sort-label').hidden=view==='lessons'||view==='playlists';$('.view-controls').hidden=view==='lessons'||view==='playlists';
if(view==='lessons'){const lessons=LESSON_NAMES.map((name,i)=>({name,n:i+1})).filter(l=>(category==='all'||lessonGroup(l.n)===category)&&(!query||(`${l.n} ${l.name}`).toLowerCase().includes(query.toLowerCase())));$('#results-count').textContent=lessons.length+' lessons';$('#content').innerHTML=lessons.length?`<div class="lesson-grid">${lessons.map(l=>{const items=ALL.filter(v=>supportsLesson(v,l.n)&&(!practiceOnly||v.kind==='practice'));return `<button class="lesson-card" data-lesson="${l.n}"><small>LESSON ${l.n}</small><strong>${esc(l.name)}</strong><span>${items.length?items.length+' supporting resource'+(items.length>1?'s':''):'Resource still to be found'}</span></button>`}).join('')}</div>`:empty('No lessons found','Try another sound or lesson number.');}
else if(view==='playlists'){const groups=GROUPS.slice(1).filter(g=>(category==='all'||category===g[0])&&(!query||g[1].toLowerCase().includes(query.toLowerCase())));$('#content').innerHTML=`<div class="playlist-grid">${groups.map((g,i)=>{const n=ALL.filter(v=>(v.group===g[0]||(v.groups||[]).includes(g[0]))&&(!practiceOnly||v.kind==='practice')).length;return `<button class="playlist-card" data-playlist="${g[0]}" style="--tone:${tones[i%6]}"><div class="playlist-art">${['a b c','a e i','sh ch','a_e','-ed','ar','ai ay','un-'][GROUPS.findIndex(x=>x[0]===g[0])-1]}</div><h3>${g[1]}</h3><p>${n} discoveries · follow lesson order</p></button>`}).join('')}</div>`;if(!groups.length)$('#content').innerHTML=empty('No playlists found','Try a sound category such as short vowels.');}
else{let items=ALL.filter(matches);if(view==='saved')items=items.filter(v=>saved.includes(v.id));if(view==='history')items=items.filter(v=>history.includes(v.id));const sort=$('#sort').value;items.sort(sort==='shortest'?(a,b)=>a.seconds-b.seconds:sort==='title'?(a,b)=>a.title.localeCompare(b.title):view==='history'?(a,b)=>history.indexOf(a.id)-history.indexOf(b.id):(a,b)=>a.lesson-b.lesson||(a.kind==='practice'?-1:1));$('#results-count').textContent=items.length+' discoveries';$('#content').innerHTML=items.length?`<div class="cards ${layout==='list'?'list':''}">${items.map(card).join('')}</div>`:view==='saved'?empty('Save your next little discovery','Tap the bookmark on a resource and it will be waiting here.'):view==='history'?empty('Your adventure starts here','Open a video or word practice to start your exploration history.'):selectedLesson?empty('A little gap in our library','We haven’t found a suitable resource for this lesson yet. Explore another lesson or try the built-in word practice.'):empty('That sound is still hiding','Try another search, choose All discoveries, or switch off Practice only for video links.');}icons();}
function navigate(v){view=v;selectedLesson=null;category='all';query='';$('#search').value='';$('.sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})}
function track(id){history=[id,...history.filter(x=>x!==id)].slice(0,100);write('history',history)}
function openResource(id){active=ALL.find(v=>v.id===id);if(!active)return;track(id);$('#dialog-kicker').textContent=lessonLabel(active)+' · '+(active.kind==='practice'?'WORD PRACTICE':active.creator.toUpperCase());wordIndex=0;revealed=false;finished=false;if(active.kind==='practice')renderPractice();else renderVideo();$('#player').showModal();render()}
function renderVideo(){const v=active;$('#player-body').innerHTML=`<div class="player-content"><div class="video-placeholder"><span class="big-sound">${esc(v.sound)}</span><p>This video plays on YouTube. It may be unavailable in mainland China. Load it when you’re ready, or try word practice instead.</p><button class="primary" id="load-video"><i data-icon="play"></i> Load YouTube video · ${time(v.seconds)}</button></div><h2>${esc(v.title)}</h2><p>${esc(v.creator)} · ${time(v.seconds)} · ${v.lessons?'supporting lessons '+v.lessons.join(', '):lessonLabel(v).toLowerCase()}</p>${v.accent?`<p class="accent-note">Pronunciation: ${esc(v.accent)}</p>`:''}<div class="alignment"><strong>A little teaching note</strong><br>${esc(v.note)} Full instructional review is still pending.</div><div class="player-actions"><button class="secondary" id="modal-save">${saved.includes(v.id)?'Remove from watch later':'Save for later'}</button><a class="secondary" href="https://www.youtube.com/watch?v=${v.youtube}" target="_blank" rel="noopener noreferrer">Open on YouTube</a><button class="secondary" id="switch-practice">Try word practice</button></div></div>`;$('#load-video').onclick=()=>{const box=$('.video-placeholder');if(v.directUrl&&v.permission==='granted'){const video=document.createElement('video');video.controls=true;video.className='video-frame';video.src=v.directUrl;box.replaceWith(video)}else{const frame=document.createElement('iframe');frame.className='video-frame';frame.title=v.title;frame.src=`https://www.youtube-nocookie.com/embed/${v.youtube}?rel=0`;frame.allow='encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;box.replaceWith(frame)}};$('#modal-save').onclick=()=>{toggleSave(v.id);$('#modal-save').textContent=saved.includes(v.id)?'Remove from watch later':'Save for later'};$('#switch-practice').onclick=()=>switchPractice();icons()}
function switchPractice(id){active=PRACTICE.find(p=>p.id===id)||PRACTICE.find(p=>p.group===active?.group)||PRACTICE[0];wordIndex=0;revealed=false;finished=false;track(active.id);$('#dialog-kicker').textContent=lessonLabel(active)+' · WORD PRACTICE';renderPractice()}
function renderPractice(){const p=active;const w=p.words[wordIndex];$('#player-body').innerHTML=`<div class="player-content"><h2>${esc(p.title)}</h2><p>Say the sounds together. Blend them into a word.</p><div class="practice-picker">${PRACTICE.map(x=>`<button data-practice="${x.id}" class="${x.id===p.id?'active':''}">Lesson ${x.lesson}</button>`).join('')}</div><div class="practice-stage">${finished?`<span class="completion">✦</span><h2>A little more confident.</h2><p>You explored ${p.words.length} words. Give your reading partner a high five!</p><div class="controls"><button class="primary" id="restart">Practise again</button></div>`:`<div class="counter">WORD ${wordIndex+1} OF ${p.words.length}</div><div class="word ${!revealed&&w.length>1?'chunked':''}" aria-label="${w.join('')}">${revealed?esc(w.join('')):w.map(s=>`<span>${esc(s)}</span>`).join('')}</div><p class="hint">${revealed?'Read the whole word. You’ve got this.':w.length===1?'Read the word. Notice the vowel pattern.':'Point to each sound. Then blend them together.'}</p><div class="controls"><button class="secondary" id="prev-word" ${wordIndex===0?'disabled':''}>Previous</button><button class="primary" id="blend-word">${revealed?'Show the sounds':'Blend the word'}</button><button class="secondary" id="next-word">${wordIndex===p.words.length-1?'Finish':'Next word'}</button></div>`}</div><div class="alignment"><strong>Practice note</strong><br>${esc(p.note)} No audio is played. A grown-up can model the sounds.</div><p style="font-size:12px">Original word cards · self-paced · works without YouTube</p></div>`;if(!finished){$('#prev-word').onclick=()=>{if(wordIndex>0){wordIndex--;revealed=false;renderPractice()}};$('#next-word').onclick=()=>{if(wordIndex<p.words.length-1)wordIndex++;else finished=true;revealed=false;renderPractice()};$('#blend-word').onclick=()=>{revealed=!revealed;renderPractice()}}else $('#restart').onclick=()=>{wordIndex=0;finished=false;revealed=false;renderPractice()};$$('[data-practice]').forEach(b=>b.onclick=()=>switchPractice(b.dataset.practice));icons()}
$('#content').onclick=e=>{const o=e.target.closest('[data-open]'),s=e.target.closest('[data-save]'),l=e.target.closest('[data-lesson]'),p=e.target.closest('[data-playlist]');if(o)openResource(o.dataset.open);if(s)toggleSave(s.dataset.save);if(l){selectedLesson=+l.dataset.lesson;view='home';category='all';query='';$('#search').value='';render();$('#hero').hidden=true;$('.library').scrollIntoView({behavior:'smooth'})}if(p){view='home';category=p.dataset.playlist;selectedLesson=null;query='';$('#search').value='';render();$('.library').scrollIntoView({behavior:'smooth'})}if(e.target.closest('#reset'))navigate('home')};
$('#filters').onclick=e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;selectedLesson=null;render()}};$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('.brand').onclick=()=>navigate('home');$('#search').oninput=e=>{query=e.target.value;selectedLesson=null;render()};$('#sort').onchange=render;$('#grid-view').onclick=()=>{layout='grid';$('#grid-view').classList.add('selected');$('#list-view').classList.remove('selected');render()};$('#list-view').onclick=()=>{layout='list';$('#list-view').classList.add('selected');$('#grid-view').classList.remove('selected');render()};$('#mode').onclick=()=>{practiceOnly=!practiceOnly;write('practice',practiceOnly);render();toast(practiceOnly?'Built-in practice, with no YouTube needed.':'Showing videos and built-in practice.')};$('#explore-button').onclick=()=>$('.library').scrollIntoView({behavior:'smooth'});['#hero-practice','#practice-side','#bottom-practice'].forEach(s=>$(s).onclick=()=>openResource(PRACTICE[0].id));['#family-link','#parent-button','#footer-info'].forEach(s=>$(s).onclick=()=>$('#info').showModal());$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>{if(d.id==='player')$('#player-body').innerHTML=''})});$('#clear-data').onclick=()=>{saved=[];history=[];write('saved',[]);write('history',[]);render();toast('Saved resources and history cleared on this browser.')};$('.mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();$('#search').focus()}if(e.key==='Escape')$('.sidebar').classList.remove('open')});render();
